from collections import deque


def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1
    if not banned:
        return pow(len(alphabet), n, MOD)

    children: list[dict[str, int]] = [{}]
    bad: list[bool] = [False]

    for word in banned:
        node = 0
        for ch in word:
            nxt = children[node].get(ch)
            if nxt is None:
                nxt = len(children)
                children[node][ch] = nxt
                children.append({})
                bad.append(False)
            node = nxt
        bad[node] = True

    num_states = len(children)
    fail = [0] * num_states
    go: list[dict[str, int]] = [{} for _ in range(num_states)]
    q: deque[int] = deque()

    for ch in alphabet:
        nxt = children[0].get(ch)
        if nxt is not None:
            go[0][ch] = nxt
            q.append(nxt)
        else:
            go[0][ch] = 0

    while q:
        u = q.popleft()
        fu = fail[u]
        for ch in alphabet:
            v = children[u].get(ch)
            if v is not None:
                go[u][ch] = v
                fv = go[fu][ch]
                fail[v] = fv
                if bad[fv]:
                    bad[v] = True
                q.append(v)
            else:
                go[u][ch] = go[fu][ch]

    good_idx = [-1] * num_states
    good_states: list[int] = []
    for i in range(num_states):
        if not bad[i]:
            good_idx[i] = len(good_states)
            good_states.append(i)

    k = len(good_states)
    mat = [[0] * k for _ in range(k)]
    for i, u in enumerate(good_states):
        for ch in alphabet:
            j = good_idx[go[u][ch]]
            if j != -1:
                mat[i][j] += 1

    def vec_mul(v: list[int], m: list[list[int]]) -> list[int]:
        return [sum(v[i] * m[i][j] for i in range(k)) % MOD for j in range(k)]

    def mat_mul(a: list[list[int]], b: list[list[int]]) -> list[list[int]]:
        bt = [[b[r][c] for r in range(k)] for c in range(k)]
        return [
            [sum(x * y for x, y in zip(row, col)) % MOD for col in bt]
            for row in a
        ]

    vec = [0] * k
    vec[0] = 1
    exp = n
    while exp > 0:
        if exp & 1:
            vec = vec_mul(vec, mat)
        exp >>= 1
        if exp:
            mat = mat_mul(mat, mat)

    return sum(vec) % MOD
